cpp6m1.solucao:
#include <iostream>
using namespace std;

int main() {
    const int N = 5;
    int pontos[N];
    int soma = 0;
    for (int i = 0; i < N; i++) {
        cout << "Rodada " << i + 1 << ": ";
        cin >> pontos[i];
        soma += pontos[i];
    }
    double media = static_cast<double>(soma) / N;
    cout << "Média: " << media << endl;
    cout << "Acima da média:";
    for (int i = 0; i < N; i++) {
        if (pontos[i] > media) {
            cout << " " << i + 1;
        }
    }
    cout << endl;
    return 0;
}

