#include <vector>
using namespace std;

int main() {
    vector<int> partidas;
    int pontos;
    cout << "Pontos (0 para parar): ";
    cin >> pontos;
    while (pontos != 0) {
        partidas.push_back(pontos);
        cout << "Pontos (0 para parar): ";
        cin >> pontos;
    }
    if (partidas.empty()) {
        cout << "Nenhuma partida registrada." << endl;
        return 0;
    }
    cout << "Partidas registradas: " << partidas.size() << endl;
    int melhor = 0;  // índice da melhor partida
    for (int i = 0; i < partidas.size(); i++) {
        cout << "Partida " << i + 1 << ": " << partidas[i] << " pontos" << endl;
        if (partidas[i] > partidas[melhor]) {
            melhor = i;
        }
    }
    cout << "Melhor: partida " << melhor + 1 << ", com " << partidas[melhor] << " pontos" << endl;
    return 0;
}

