#include <iostream>
#include <vector>
#include <string>
using namespace std;

int vivos(const vector<int>& vidas) {
    int total = 0;
    for (int v : vidas) {
        if (v > 0) {
            total++;
        }
    }
    return total;
}

void curarTodos(vector<int>& vidas, int cura, int vidaMaxima) {
    for (int& v : vidas) {
        if (v > 0) {
            v += cura;
            if (v > vidaMaxima) {
                v = vidaMaxima;
            }
        }
    }
}

string maisLongo(const vector<string>& nomes) {
    string maior = "";
    for (const auto& nome : nomes) {
        if (nome.size() > maior.size()) {
            maior = nome;
        }
    }
    return maior;
}

int main() {
    vector<int> vidas = {10, 0, 18};
    cout << "Vivos: " << vivos(vidas) << endl;
    curarTodos(vidas, 5, 20);
    cout << "Depois da cura: " << vidas[0] << " " << vidas[1] << " " << vidas[2] << endl;
    cout << "Nome mais longo: " << maisLongo({"Ana", "Rafa", "Duda"}) << endl;
    return 0;
}

