#include <iostream>
#include <string>
#include <cctype>
using namespace std;

string minusculas(string texto) {
    for (char& c : texto) {
        c = tolower(c);
    }
    return texto;
}

string verbo(const string& comando) {
    auto espaco = comando.find(' ');
    if (espaco == string::npos) {
        return comando;
    }
    return comando.substr(0, espaco);
}

string alvo(const string& comando) {
    auto espaco = comando.find(' ');
    if (espaco == string::npos) {
        return "";
    }
    return comando.substr(espaco + 1);
}

int main() {
    string comando;
    cout << "Comando: ";
    getline(cin, comando);
    comando = minusculas(comando);
    cout << "Verbo: " << verbo(comando) << endl;
    cout << "Alvo: " << alvo(comando) << endl;
    return 0;
}

