#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<int> ranking(vector<int> pontos) {
    sort(pontos.begin(), pontos.end());
    reverse(pontos.begin(), pontos.end());
    return pontos;
}

int recordistas(const vector<int>& pontos) {
    if (pontos.empty()) {
        return 0;
    }
    int maior = *max_element(pontos.begin(), pontos.end());
    return count(pontos.begin(), pontos.end(), maior);
}

bool jogou(const vector<string>& jogadores, const string& nome) {
    return find(jogadores.begin(), jogadores.end(), nome) != jogadores.end();
}

int main() {
    vector<int> r = ranking({30, 80, 50});
    cout << "Primeiro do ranking: " << r[0] << endl;
    cout << "Recordistas: " << recordistas({80, 30, 80, 50}) << endl;
    cout << "Leo jogou? " << (jogou({"Ana", "Leo"}, "Leo") ? "sim" : "não") << endl;
    return 0;
}

