#include <iostream>
#include <iomanip>
#include <vector>
#include <string>
#include <cctype>
#include <algorithm>
using namespace std;

string formatarNome(string nome) {
    for (char& c : nome) {
        c = tolower(c);
    }
    if (!nome.empty()) {
        nome[0] = toupper(nome[0]);
    }
    return nome;
}

double media(const vector<double>& notas) {
    if (notas.empty()) {
        return 0.0;
    }
    double soma = 0;
    for (double n : notas) {
        soma += n;
    }
    return soma / notas.size();
}

string situacao(double media) {
    if (media >= 7) {
        return "aprovado";
    }
    if (media >= 5) {
        return "recuperação";
    }
    return "reprovado";
}

double mediana(vector<double> valores) {
    if (valores.empty()) {
        return 0.0;
    }
    sort(valores.begin(), valores.end());
    int meio = valores.size() / 2;
    if (valores.size() % 2 == 1) {
        return valores[meio];
    }
    return (valores[meio - 1] + valores[meio]) / 2;
}

int main() {
    int quantidade;
    cout << "Quantos alunos? ";
    cin >> quantidade;
    vector<string> nomes;
    vector<double> medias;
    for (int i = 0; i < quantidade; i++) {
        string nome;
        double n1, n2, n3;
        cout << "Nome: ";
        cin >> nome;
        cout << "Notas: ";
        cin >> n1 >> n2 >> n3;
        nomes.push_back(formatarNome(nome));
        medias.push_back(media({n1, n2, n3}));
    }
    cout << "--- Boletim ---" << endl;
    cout << fixed << setprecision(1);
    for (int i = 0; i < nomes.size(); i++) {
        cout << nomes[i] << ": " << medias[i] << " (" << situacao(medias[i]) << ")" << endl;
    }
    cout << "Mediana da turma: " << mediana(medias) << endl;
    int melhor = max_element(medias.begin(), medias.end()) - medias.begin();
    cout << "Melhor média: " << nomes[melhor] << endl;
    return 0;
}
